/**
 * @file    stm32n6xx_ll_crc.h
 * @brief   CRC LL driver candidate: independent data register (CRC_IDR) only.
 *
 * Header-only LL access to the general-purpose 32-bit independent data
 * register CRC_IDR of the STM32N6 CRC peripheral.
 *
 * Hardware source: RM0486 Rev4 section 26.4.2 (CRC_IDR), p.1172 -
 * bits IDR[31:0] are read/write general-purpose data bits at address
 * offset 0x04; the register is not affected by CRC resets generated by
 * the RESET bit in CRC_CR. The register layout (CRC_TypeDef, IDR at
 * offset 0x04) comes from the immutable source-backed fixture
 * inputs/forge_crc_device.h.
 *
 * Invocation domain (IDR-CONTRACT.md):
 *  - CRCx is a valid accessible CRC_TypeDef instance supplied by the
 *    caller; clock/power/security and access setup are caller-owned
 *    preconditions, not performed or inferred here.
 *  - No startup accesses, status polling, allocation, masking or setup
 *    occur in this scope.
 *  - Out of scope: CRC calculation/feed, polynomial/INIT configuration,
 *    reversal, calculation-unit reset, DMA, HAL, invalid pointers.
 */
#ifndef STM32N6XX_LL_CRC_H
#define STM32N6XX_LL_CRC_H

#include "forge_crc_device.h"

/**
 * @brief  Write the supplied 32-bit value to CRC_IDR.IDR.
 * @param  CRCx  Pointer to a valid accessible CRC_TypeDef instance.
 * @param  InData  32-bit value; all 32 bits IDR[31:0] are written.
 * @retval None
 *
 * @note  Full 32-bit write to the rw IDR field; no other register of
 *        the instance (or of any other instance) is read, written or
 *        otherwise modified.
 */
static inline void LL_CRC_Write_IDR(CRC_TypeDef *CRCx, uint32_t InData)
{
    CRCx->IDR = InData;
}

/**
 * @brief  Read the 32-bit value currently stored in CRC_IDR.IDR.
 * @param  CRCx  Pointer to a valid accessible CRC_TypeDef instance.
 * @retval 32-bit value stored in IDR[31:0].
 *
 * @note  Read-only access to the rw IDR field; the register value is
 *        unchanged by the read and no other register is modified.
 */
static inline uint32_t LL_CRC_Read_IDR(const CRC_TypeDef *CRCx)
{
    return CRCx->IDR;
}

#endif /* STM32N6XX_LL_CRC_H */
